function HouseholdGate({account,households,onCreate,onJoin,onSignOut}){const [mode,setMode]=useState('create'),[message,setMessage]=useState('');const submit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.currentTarget));if(mode==='create'){onCreate(v.name.trim());return}const code=v.code.trim().toUpperCase();const household=households.find(h=>h.inviteCode===code);if(!household){setMessage('That invite code was not found in this browser prototype.');return}onJoin(household)};return <main className="auth-shell" onInputCapture={capitalizeFirstLetter}><div className="auth-card"><div className="brand auth-brand">Chill<span>Allot</span></div><div className="eyebrow">SIGNED IN AS {account.name.toUpperCase()}</div><h1>Start your household</h1><p className="modal-description">Create a home for your shared bills, shopping, appointments, and chores, or join one with an invite code.</p><div className="pills household-tabs"><button className={mode==='create'?'selected':''} onClick={()=>{setMode('create');setMessage('')}}>Create household</button><button className={mode==='join'?'selected':''} onClick={()=>{setMode('join');setMessage('')}}>Join household</button></div><form autoComplete="off" onSubmit={submit}>{mode==='create'?<label>Household name<input autoComplete="off" name="name" placeholder="Give your household a name" required/></label>:<label>Invitation link or code<input data-preserve-input autoComplete="off" name="code" placeholder="Paste the invitation link or code" required/></label>}{message&&<p className="form-message">{message}</p>}<button className="primary auth-submit" type="submit">{mode==='create'?'Create household':'Join household'}</button></form><button className="text-button auth-switch" onClick={onSignOut}>Sign out</button></div></main>}
function makeId(){return globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`}
function dateOffset(date,days){const d=new Date(`${date}T12:00:00`);d.setDate(d.getDate()+days);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function localISO(date=new Date()){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
function nextOccurrence(date,cadence){const d=new Date(`${date}T12:00:00`),originalDay=d.getDate(),originalMonth=d.getMonth();let count=1,unit='';const custom=(cadence||'').match(/^Every (\d+) (days?|weeks?|months?|years?)$/i);if(custom){count=Number(custom[1]);unit=custom[2].toLowerCase().replace(/s$/,'')}else if(cadence?.includes('Monthly'))unit='month';else if(cadence==='Annually')unit='year';else if(cadence==='Weekly')unit='week';else return date;if(unit==='day')d.setDate(d.getDate()+count);else if(unit==='week')d.setDate(d.getDate()+7*count);else if(unit==='month'){d.setDate(1);d.setMonth(d.getMonth()+count);d.setDate(Math.min(originalDay,new Date(d.getFullYear(),d.getMonth()+1,0).getDate()))}else if(unit==='year'){d.setDate(1);d.setFullYear(d.getFullYear()+count);d.setMonth(originalMonth);d.setDate(Math.min(originalDay,new Date(d.getFullYear(),d.getMonth()+1,0).getDate()))}return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function App(){const [accounts,setAccounts]=useSavedState('chillallot.accounts',[]),[account,setAccount]=useSavedState('chillallot.account',null),[households,setHouseholds]=useSavedState('chillallot.households',[]),[preview,setPreview]=useState(true);const signOut=()=>setAccount(null);const createHousehold=name=>{const household={id:makeId(),name,inviteCode:Math.random().toString(36).slice(2,8).toUpperCase(),members:[{name:account.name,email:account.email,role:'Owner'}]};setHouseholds(items=>[...items,household]);};const joinHousehold=household=>{const updated={...household,members:[...household.members,{name:account.name,email:account.email,role:'Member'}]};setHouseholds(items=>items.map(item=>item.id===household.id?updated:item))};if(preview)return <Dashboard key="preview" preview account={{id:'preview',name:'Preview user',email:''}} household={{id:'preview',name:'App preview',members:[]}} onSignOut={()=>{setPreview(false);signOut()}}/>;if(!account)return <AuthFlow accounts={accounts} onAccount={user=>{setAccounts(items=>[...items,user]);setAccount(user)}} onPreview={()=>setPreview(true)}/>;const household=households.find(h=>h.members?.some(m=>m.email===account.email));if(!household)return <HouseholdGate account={account} households={households} onCreate={createHousehold} onJoin={joinHousehold} onSignOut={signOut}/>;return <Dashboard key={household.id} account={account} household={household} onSignOut={signOut}/>}
function useSavedState(key,initial){const [value,setValue]=useState(()=>{removeReferenceRows();try{return JSON.parse(localStorage.getItem(key))??initial}catch{return initial}});React.useEffect(()=>{try{localStorage.setItem(key,JSON.stringify(value))}catch{}},[key,value]);return [value,setValue]}

function useSyncedState(key,initial,householdId,cloud,dataKey){
 const [value,setValue]=useState(()=>{try{return JSON.parse(localStorage.getItem(key))??initial}catch{return initial}}),[ready,setReady]=useState(!cloud);
 React.useEffect(()=>{try{localStorage.setItem(key,JSON.stringify(value))}catch{}},[key,value]);
 React.useEffect(()=>{if(!cloud){setReady(true);return}let active=true;setReady(false);readHouseholdData(householdId,dataKey).then(payload=>{if(!active)return;if(payload!==null)setValue(payload);setReady(true)}).catch(error=>{console.error('Could not load household data:',error);if(active)setReady(true)});const channel=supabase.channel(`household-data-${householdId}-${dataKey}`).on('postgres_changes',{event:'*',schema:'public',table:'household_data',filter:`household_id=eq.${householdId}`},event=>{if(active&&event.new?.data_key===dataKey){const incoming=event.new.payload;setValue(current=>JSON.stringify(current)===JSON.stringify(incoming)?current:incoming)}}).subscribe();return()=>{active=false;supabase.removeChannel(channel)}},[cloud,householdId,dataKey]);
 React.useEffect(()=>{if(!cloud||!ready)return;const timer=setTimeout(()=>{writeHouseholdData(householdId,dataKey,value).catch(error=>console.error('Could not save household data:',error))},250);return()=>clearTimeout(timer)},[cloud,ready,householdId,dataKey,value]);
 return [value,setValue];
}

